import json
with open('plato_tasks.json') as f: d=json.load(f)
# find entry
def find(o, qid):
    if isinstance(o, dict):
        if o.get('question_id')==qid or o.get('id')==qid:
            return o
        for v in o.values():
            r=find(v,qid)
            if r: return r
    elif isinstance(o, list):
        for v in o:
            r=find(v,qid)
            if r: return r
    return None
